session_start(); require_once __DIR__.'/../lead-engine/config.php';
require_once __DIR__ . '/includes/goliath-ui.php';
if(empty($_SESSION['mp_dashboard_auth'])){header('Location:/dashboard/?next=/dashboard/goliath-communications.php');exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sb($ep){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY],CURLOPT_TIMEOUT=>30]);$b=curl_exec($ch);curl_close($ch);$d=json_decode($b,true);return is_array($d)?$d:[];}
$key=defined('AFTER_HOURS_CRON_KEY')?AFTER_HOURS_CRON_KEY:'timetomakethedonuts';
$leads=sb('leads?select=*&order=created_at.desc&limit=25');
$logFile=defined('LOG_PATH')?LOG_PATH.'/lead-engine-'.date('Y-m').'.log':__DIR__.'/../lead-engine/logs/lead-engine-'.date('Y-m').'.log';
$logs=[]; if(file_exists($logFile)){ $lines=array_slice(file($logFile,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES),-80); foreach($lines as $line){$j=json_decode($line,true); if(is_array($j))$logs[]=$j;} }
$adminOk=0;$userOk=0;$adminErr=0;$userErr=0;foreach($logs as $l){if(($l['service']??'')==='Resend Admin'){(($l['status']??'')==='success')?$adminOk++:$adminErr++;} if(($l['service']??'')==='Resend User'){(($l['status']??'')==='success')?$userOk++:$userErr++;}}
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Goliath Communications</title><style>
