</style><link rel="stylesheet" href="/dashboard/assets/goliath-os.css?v=4"><link rel="icon" href="/dashboard/assets/goliath-ai-full-logo.png?v=4"><?php goliath_ui_head(); ?></head><body><?php goliath_ui_open(); ?><section class="hero"><h1>Goliath Communications</h1><p>Lead emails, Resend diagnostics, and incoming lead action feed.</p></section><main class="wrap">
<p><a class="btn" target="_blank" href="/lead-engine/resend-diagnostic.php?key=<?=h($key)?>">Run Resend Test</a><a class="btn" target="_blank" href="/lead-engine/capture-diagnostic.php?key=<?=h($key)?>">Run Full Capture Test</a><a class="btn" href="/dashboard/owner-research-queue.php">Owner Queue</a></p>
<section class="grid"><div class="card"><div class="metric"><?=count($leads)?></div><strong>Recent Leads</strong></div><div class="card"><div class="metric"><?=$adminOk?></div><strong>Admin Emails OK</strong></div><div class="card"><div class="metric"><?=$userOk?></div><strong>User Emails OK</strong></div><div class="card"><div class="metric"><?=($adminErr+$userErr)?></div><strong>Email Errors</strong></div></section>
<section class="panel"><h2>Recent Leads</h2><div class="row head"><div>Name</div><div>Contact / Property</div><div>Type</div><div>Score</div></div><?php foreach($leads as $l):?><div class="row"><div><strong><?=h($l['name']??'')?></strong><br><span class="small"><?=h($l['created_at']??'')?></span></div><div><?=h($l['email']??'')?> · <?=h($l['phone']??'')?><br><span class="small"><?=h($l['address']??'')?> <?=h($l['town']??'')?></span></div><div><?=h($l['type']??'')?></div><div><?=h($l['lead_score']??$l['adaptive_score']??'')?></div></div><?php endforeach;?></section>
<section class="panel"><h2>Recent Lead-Engine Email Logs</h2><pre><?php foreach(array_reverse($logs) as $l){ if(in_array($l['service']??'',['Resend Admin','Resend User','Hot Lead Alert','Capture'])) echo h(json_encode($l,JSON_PRETTY_PRINT))."\n\n"; } ?></pre></section>
